module PermutationShiftOptimizer(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] p_0,\n    input wire [3:0] p_1,\n    input wire [3:0] p_2,\n    input wire [3:0] p_3,\n    input wire [3:0] p_4,\n    input wire [3:0] p_5,\n    input wire [3:0] p_6,\n    input wire [3:0] p_7,\n    input wire [3:0] n,\n    output reg [15:0] min_deviation,\n    output reg [3:0] best_shift,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE   = 2'd0;\n    localparam [1:0] LOAD   = 2'd1;\n    localparam [1:0] COMPUTE = 2'd2;\n    localparam [1:0] DONE   = 2'd3;\n\n    reg [1:0] state;\n    reg [3:0] shift_counter;\n    reg [3:0] element_counter;\n    reg [15:0] current_deviation;\n    reg [3:0] perm [0:7];\n    integer i;\n    \n    // Combinational target position\n    wire [4:0] sum_pos = element_counter + shift_counter;\n    wire [3:0] target_pos = (sum_pos >= n) ? (sum_pos - n) : sum_pos[3:0];\n    wire [4:0] target_val = {1'b0, target_pos} + 5'd1;\n    \n    // Element value\n    wire [3:0] elem_value;\n    assign elem_value = perm[element_counter];\n    \n    // Deviation calculation\n    wire [4:0] diff = {1'b0, elem_value} - target_val;\n    wire [4:0] abs_diff = diff[4] ? (~diff + 1'b1) : diff;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            min_deviation <= 16'hFFFF;\n            best_shift <= 4'd0;\n            shift_counter <= 4'd0;\n            element_counter <= 4'd0;\n            current_deviation <= 16'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                perm[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                        element_counter <= 4'd0;\n                    end\n                end\n                \n                LOAD: begin\n                    case (element_counter)\n                        4'd0: perm[0] <= p_0;\n                        4'd1: perm[1] <= p_1;\n                        4'd2: perm[2] <= p_2;\n                        4'd3: perm[3] <= p_3;\n                        4'd4: perm[4] <= p_4;\n                        4'd5: perm[5] <= p_5;\n                        4'd6: perm[6] <= p_6;\n                        4'd7: perm[7] <= p_7;\n                    endcase\n                    \n                    if (element_counter == (n - 1'b1)) begin\n                        state <= COMPUTE;\n                        element_counter <= 4'd0;\n                        shift_counter <= 4'd0;\n                        current_deviation <= 16'd0;\n                    end else begin\n                        element_counter <= element_counter + 1'b1;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (element_counter < n) begin\n                        current_deviation <= current_deviation + {11'd0, abs_diff};\n                        element_counter <= element_counter + 1'b1;\n                    end else begin\n                        if (current_deviation < min_deviation) begin\n                            min_deviation <= current_deviation;\n                            best_shift <= shift_counter;\n                        end\n                        \n                        if (shift_counter == (n - 1'b1)) begin\n                            state <= DONE;\n                        end else begin\n                            shift_counter <= shift_counter + 1'b1;\n                            element_counter <= 4'd0;\n                            current_deviation <= 16'd0;\n                        end\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule